  // 다음: 노드 5 · 오늘 뭐 할까요?
  // 듣고 말하기 + 여가 활동 제안 통합
  //
  // 시간이 언제 있어요?
  // 그때 뭘 해요?
  // 영화를 좋아해요.
  // 극장에 자주 가요.
  // 그럼 오늘 오후에 같이 영화 볼까요?
  // ══════════════════════════════════════════════════════════
