  // ══════════════════════════════════════════════════════════
  // 노드 5 · 레슨 4 — 시간 → 활동 → 제안
  // p.196~197 실전 통합
  //
  // 언제 시간이 있어요?
  // 오후에 시간이 있어요.
  // 그럼 오후에 뭘 해요?
  // 극장에서 영화를 봐요.
  // 저도 영화를 좋아해요.
  // 그럼 오늘 오후에 같이 영화 볼까요?
